/** The grammar bits, as data: every rule GRAMMAR.md's tables list.
 *
 *  A rule here is a bit the learner can open on the Grammar screen and be
 *  asked in a sitting; its id is the record's id for ever, and the document
 *  is the one place a rule is described in prose. This file is generated
 *  from the document's tables and kept equal to them by
 *  tests/grammar-rules.test.ts, which parses the document itself: a rule
 *  added, renamed or re-wired in one and not the other fails there. Do not
 *  edit the rows by hand; edit GRAMMAR.md and regenerate
 *  (scripts/grammar-rules.py).
 *
 *  `needs` is what a rule builds on and `after` the order learners are
 *  observed to take; both are advice the screen states, never a lock: every
 *  bit is opt-in, and the learner picks. `faces` is how the rule is
 *  practised (GRAMMAR.md, "Generators, faces, and how many at once"), and
 *  `placed` where the syllabus and Kwiziq put it.
 */

/** The ten modules of the inventory, by the letter of their ids. */
export type Module = "sounds" | "numbers" | "nouns" | "adjectives" | "pronouns" | "verbs" | "negation" | "questions" | "connectors" | "sentences";

/** How a rule is put in front of the learner. */
export type Face = "read" | "choose" | "gap" | "which" | "say" | "hear" | "transform" | "order" | "mark" | "spell";

export interface RuleSpec {
  readonly module: Module;
  /** The rule in one sentence, as the document's table states it. */
  readonly what: string;
  readonly needs: readonly string[];
  readonly after: readonly string[];
  readonly faces: readonly Face[];
  readonly placed: string;
}

