export type RuleId = keyof typeof RULES;

export const RULE_IDS: readonly RuleId[] = Object.keys(RULES) as RuleId[];

export const isRuleId = (value: unknown): value is RuleId =>
  typeof value === 'string' && value in RULES;

/** The rule, for an id that may have come from a record. */
export const ruleOf = (id: string): RuleSpec | null => (isRuleId(id) ? RULES[id] : null);
